<script setup>
import {onMounted,onUnmounted,nextTick,ref,computed,watch} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import NodeFacts from '../components/NodeFacts.vue'
import DynamicGroupEditor from '../forms/DynamicGroupEditor.vue'
import {api,session} from '../services/api.js'
import {activeTheme} from '../lib/theme.js'
const nodes=ref([]),groups=ref([]),credentials=ref([]),search=ref(''),assetFilter=ref('all'),assetPage=ref(1),assetPageSize=ref(25),assetSort=ref('priority'),assetSortDir=ref('asc'),groupName=ref(''),memberGroup=ref(''),formOpen=ref(false),detailOpen=ref(false),editOpen=ref(false),deleteOpen=ref(false),auditEnableOpen=ref(false),auditConfirmation=ref(false),deleteConfirmation=ref(false),editForm=ref({hostname:'',fqdn:'',ip:'',deviceType:'auto',managementType:'auto'}),selected=ref(null),credentialSelection=ref([]),error=ref(''),message=ref(''),busy=ref(false),form=ref({hostname:'',fqdn:'',ip:'',credentialIds:[]})
const canEdit=computed(()=>['owner','admin','editor'].includes(session.user?.role))
const canDelete=computed(()=>['owner','admin'].includes(session.user?.role))
const retrainDays=ref(7),trainingDays=ref(30)
const rulePage=ref(null),rulesLoading=ref(false),rulesError=ref('')
const auditPolicy=ref(null),auditLoading=ref(false),auditError=ref('')
const contextMenu=ref(null),contextMenuEl=ref(null),enrollmentOpen=ref(false),enrollmentNode=ref(null),enrollmentToken=ref(null),enrollmentError=ref(''),enrollmentBusy=ref(false),tokenCopied=ref(false)
const groupOpen=ref(false),selectedGroup=ref(null),groupError=ref(''),confirmOpen=ref(false),confirmMessage=ref(''),confirmAction=ref(null),confirmBusy=ref(false)
const dynamicGroup=ref({enabled:false,match:'all',rules:[]}),selectedGroupDynamic=ref({enabled:false,match:'all',rules:[]}),dynamicGroupSaving=ref(false)
const breakGlassOpen=ref(false),breakGlassNode=ref(null),breakGlassState=ref(null),breakGlassForm=ref({durationMinutes:30,reason:'',confirmed:false}),breakGlassBusy=ref(false),breakGlassError=ref('')
const locationOrigin=window.location.origin
const activeTab=ref('assets')
const canEnroll=node=>canDelete.value&&!!node?.ad_guid&&!node?.ad_missing&&!node?.agent_id
const canDeploy=node=>canDelete.value&&node?.connection_mode==='agentless'&&['winrm','winrms'].includes(node?.transport)&&!node?.agent_id
// AD discovered hosts can be re-verified at any time. This keeps the action
// available after a transient WinRM failure left an older row marked
// Unchecked, and makes the operation idempotent for already verified hosts.
const canActivate=node=>canDelete.value&&node?.connection_mode==='agentless'&&!!node?.ad_guid&&!node?.ad_missing&&!!node?.ad_enabled&&!node?.agent_id
const canBreakGlass=node=>canDelete.value&&(node?.connection_mode==='agent'||['winrm','winrms'].includes(node?.transport))
function managementCheck(node){if(node?.connection_mode==='agent'&&node.status==='reachable')return 'Agent connected';if(node?.transport==='wmi'){if(node.probe_status==='rpc-authenticated')return 'RPC authenticated';if(node.probe_status==='wmi-authenticated')return 'WMI credential authenticated';return 'RPC not verified'}if(node?.transport==='netsh')return node.status==='reachable'?'SMB/netsh authenticated':'SMB service open';if(['winrm','winrms'].includes(node?.transport))return node.status==='reachable'?'WinRM authenticated':'WinRM port open';return 'No management connection'}
function closeContextMenu(){contextMenu.value=null}
function openContextMenu(event,node){
  event.preventDefault();event.stopPropagation()
  const rect=event.currentTarget.getBoundingClientRect()
  const x=Math.max(8,Math.min(event.clientX||rect.left,window.innerWidth-230))
  const y=Math.max(8,Math.min(event.clientY||rect.bottom,window.innerHeight-195))
  contextMenu.value={node,x,y}
  nextTick(()=>contextMenuEl.value?.querySelector('button')?.focus({preventScroll:true}))
}
function onWindowPointer(event){if(contextMenu.value&&!event.target.closest('.asset-context-menu,.asset-menu-trigger'))closeContextMenu()}
function onWindowKey(event){if(event.key==='Escape')closeContextMenu()}
onMounted(()=>{window.addEventListener('pointerdown',onWindowPointer);window.addEventListener('keydown',onWindowKey)})
onUnmounted(()=>{window.removeEventListener('pointerdown',onWindowPointer);window.removeEventListener('keydown',onWindowKey)})
function beginEnrollment(node){closeContextMenu();enrollmentNode.value=node;enrollmentToken.value=null;enrollmentError.value='';tokenCopied.value=false;enrollmentOpen.value=true}
async function createEnrollmentToken(){if(!canEnroll(enrollmentNode.value))return;enrollmentBusy.value=true;enrollmentError.value='';try{enrollmentToken.value=await api('/agents/enrollment-tokens',{method:'POST',body:{nodeId:enrollmentNode.value.id}})}catch(e){enrollmentError.value=e.message}finally{enrollmentBusy.value=false}}
async function activateAgentless(node){closeContextMenu();busy.value=true;error.value='';message.value=`Verifying ${node.hostname} with the directory WinRM credential…`;try{const result=await api(`/nodes/${node.id}/activate-agentless`,{method:'POST',body:{}});message.value=`${result.computerName} verified and managed over ${result.transport.toUpperCase()}`;selected.value=await api(`/nodes/${node.id}`);detailOpen.value=true;await load()}catch(cause){message.value='';error.value=cause.message}finally{busy.value=false}}
async function deployAgent(node){closeContextMenu();busy.value=true;error.value='';message.value=`Installing signed agent on ${node.hostname}…`;try{const result=await api(`/nodes/${node.id}/deploy-agent`,{method:'POST',body:{}});message.value=`WinFire Agent installed and running on ${node.hostname} (${result.serviceStatus})`;await load()}catch(cause){message.value='';error.value=cause.message}finally{busy.value=false}}
async function copyEnrollmentToken(){if(!enrollmentToken.value)return;try{await navigator.clipboard.writeText(enrollmentToken.value.token);tokenCopied.value=true}catch(e){enrollmentError.value='Copy failed. Select the token text and copy it manually.'}}
async function beginBreakGlass(node){closeContextMenu();breakGlassNode.value=node;breakGlassForm.value={durationMinutes:30,reason:'',confirmed:false};breakGlassError.value='';breakGlassOpen.value=true;await refreshBreakGlass()}
async function refreshBreakGlass(){if(!breakGlassNode.value)return;breakGlassBusy.value=true;try{breakGlassState.value=await api(`/nodes/${breakGlassNode.value.id}/break-glass`);breakGlassError.value=''}catch(e){breakGlassError.value=e.message}finally{breakGlassBusy.value=false}}
async function startBreakGlass(){if(!breakGlassNode.value)return;breakGlassBusy.value=true;breakGlassError.value='';try{const result=await api(`/nodes/${breakGlassNode.value.id}/break-glass`,{method:'POST',body:{durationMinutes:Number(breakGlassForm.value.durationMinutes),reason:breakGlassForm.value.reason.trim(),confirmed:breakGlassForm.value.confirmed}});breakGlassState.value={active:result.session,history:[result.session]};message.value=result.queued?'Break glass queued for the agent':'Break glass active; host rollback is scheduled'}catch(e){breakGlassError.value=e.message}finally{breakGlassBusy.value=false}}
async function endBreakGlass(){const active=breakGlassState.value?.active;if(!active||!breakGlassNode.value)return;breakGlassBusy.value=true;breakGlassError.value='';try{const result=await api(`/nodes/${breakGlassNode.value.id}/break-glass/end`,{method:'POST',body:{sessionId:active.id}});message.value=result.queued?'Firewall restoration queued for the agent':'Firewall profiles restored';await refreshBreakGlass()}catch(e){breakGlassError.value=e.message}finally{breakGlassBusy.value=false}}
const isSnmp=node=>node?.transport==='snmp'||node?.connection_mode==='snmp'||node?.management_type==='snmp'
const isManaged=node=>isSnmp(node)||node?.connection_mode==='agent'||node?.agent_id||node?.training?.status==='active'||(node?.firewall_state==='enforcing'&&!(node?.agent_required&&!node?.agent_id))||node?.managementVerification?.status==='reachable'
const firewallLabel=node=>isSnmp(node)?'SNMP':(node?.agent_required&&!node?.agent_id&&node?.firewall_state==='enforcing'?'Unmanaged':node?.firewall_state||'Unmanaged')
const filteredRows=computed(()=>{const term=search.value.trim().toLowerCase();let rows=nodes.value.filter(node=>!term||[node.hostname,node.fqdn,node.ip,node.os_version,node.device_type,node.transport].join(' ').toLowerCase().includes(term));if(assetFilter.value==='managed')rows=rows.filter(isManaged);if(assetFilter.value==='unmanaged')rows=rows.filter(node=>!isManaged(node));if(assetFilter.value==='reachable')rows=rows.filter(node=>node.status==='reachable');if(assetFilter.value==='unreachable')rows=rows.filter(node=>node.status==='unreachable');const value=(node,key)=>key==='priority'?(isManaged(node)?0:1):key==='hostname'?(node.hostname||'').toLowerCase():key==='address'?(node.ip||node.fqdn||'').toLowerCase():key==='status'?(node.status||'').toLowerCase():key==='mode'?(isSnmp(node)?'snmp':node.connection_mode||'').toLowerCase():'';rows.sort((a,b)=>{const priority=value(a,assetSort.value),other=value(b,assetSort.value);if(assetSort.value!=='priority'){const ap=value(a,'priority'),bp=value(b,'priority');if(ap!==bp)return ap<bp?-1:1}if(priority===other)return (a.hostname||'').localeCompare(b.hostname||'')*(assetSortDir.value==='desc'?-1:1);return (priority<other?-1:1)*(assetSortDir.value==='desc'?-1:1)});return rows})
const assetTotalPages=computed(()=>Math.max(1,Math.ceil(filteredRows.value.length/assetPageSize.value)))
const filtered=computed(()=>filteredRows.value.slice((assetPage.value-1)*assetPageSize.value,assetPage.value*assetPageSize.value))
watch([()=>filteredRows.value.length,assetPageSize],()=>{if(assetPage.value>assetTotalPages.value)assetPage.value=assetTotalPages.value})
function sortAssets(key){if(assetSort.value===key)assetSortDir.value=assetSortDir.value==='asc'?'desc':'asc';else{assetSort.value=key;assetSortDir.value='asc'}assetPage.value=1}
function changeAssetPageSize(){assetPage.value=1}
function changeAssetPage(page){assetPage.value=Math.max(1,Math.min(assetTotalPages.value,page))}
const availableGroups=computed(()=>groups.value.filter(group=>!selected.value?.groups?.some(member=>member.id===group.id)))
async function load(){
  const requests=await Promise.allSettled([api('/nodes'),api('/credentials'),api('/node-groups'),api('/settings/training')])
  const [loadedNodes,loadedCredentials,loadedGroups,settings]=requests
  if(loadedNodes.status==='fulfilled')nodes.value=loadedNodes.value
  if(loadedCredentials.status==='fulfilled')credentials.value=loadedCredentials.value
  if(loadedGroups.status==='fulfilled')groups.value=loadedGroups.value
  if(settings.status==='fulfilled')trainingDays.value=settings.value.newHostTrainingDays
  const failures=requests.filter(result=>result.status==='rejected').map(result=>result.reason?.message||'Request failed')
  error.value=failures.length?`Inventory refresh incomplete: ${failures.join('; ')}`:''
}
onMounted(load)
async function create(){busy.value=true;error.value='';try{const node=await api('/nodes',{method:'POST',body:form.value});formOpen.value=false;form.value={hostname:'',fqdn:'',ip:'',credentialIds:[]};message.value=`${node.hostname} added; ${node.training.days}-day training started`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function select(node){selected.value=await api(`/nodes/${node.id}`);credentialSelection.value=[...(selected.value.credentialIds||[])];detailOpen.value=true;rulePage.value=null;rulesError.value='';auditPolicy.value=null;auditError.value='';if(['winrm','winrms','netsh'].includes(selected.value.transport)){loadRules(0);loadAuditPolicy()}}
async function saveCredentials(){if(!selected.value)return;busy.value=true;error.value='';try{await api(`/nodes/${selected.value.id}/credentials`,{method:'PUT',body:{credentialIds:credentialSelection.value}});selected.value=await api(`/nodes/${selected.value.id}`);message.value=`Credentials updated for ${selected.value.hostname}`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadAuditPolicy(){if(!selected.value)return;auditLoading.value=true;auditError.value='';try{auditPolicy.value=await api(`/nodes/${selected.value.id}/audit-policy`)}catch(e){auditError.value=e.message}finally{auditLoading.value=false}}
function beginAuditEnable(){auditConfirmation.value=false;error.value='';detailOpen.value=false;auditEnableOpen.value=true}
async function enableAuditPolicy(){if(!selected.value||!auditConfirmation.value)return;busy.value=true;error.value='';try{auditPolicy.value=await api(`/nodes/${selected.value.id}/audit-policy/enable`,{method:'POST',body:{confirmed:true}});auditEnableOpen.value=false;detailOpen.value=true;message.value=`Traffic auditing enabled on ${selected.value.hostname}`}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadRules(offset=0){if(!selected.value)return;rulesLoading.value=true;rulesError.value='';try{rulePage.value=await api(`/nodes/${selected.value.id}/firewall-rules?offset=${offset}&limit=100`)}catch(e){rulesError.value=e.message}finally{rulesLoading.value=false}}
async function action(name){busy.value=true;error.value='';try{const result=await api(`/nodes/${selected.value.id}/${name}`,{method:'POST',body:{}});selected.value=await api(`/nodes/${selected.value.id}`);if(name==='probe')selected.value.probe=result;if(['winrm','winrms','netsh'].includes(selected.value.transport)){loadRules(0);loadAuditPolicy()}await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function createGroup(){try{await api('/node-groups',{method:'POST',body:{name:groupName.value,dynamic:dynamicGroup.value}});groupName.value='';dynamicGroup.value={enabled:false,match:'all',rules:[]};message.value='Node group created';await load()}catch(e){error.value=e.message}}
async function openGroup(group){groupError.value='';try{selectedGroup.value=await api(`/node-groups/${group.id}`);selectedGroupDynamic.value={enabled:selectedGroup.value.dynamicEnabled,match:selectedGroup.value.dynamicMatch,rules:selectedGroup.value.dynamicRules||[]};groupOpen.value=true}catch(e){groupError.value=e.message}}
async function saveDynamicGroup(){if(!selectedGroup.value)return;dynamicGroupSaving.value=true;groupError.value='';try{await api(`/node-groups/${selectedGroup.value.id}`,{method:'PATCH',body:{dynamic:selectedGroupDynamic.value}});selectedGroup.value=await api(`/node-groups/${selectedGroup.value.id}`);selectedGroupDynamic.value={enabled:selectedGroup.value.dynamicEnabled,match:selectedGroup.value.dynamicMatch,rules:selectedGroup.value.dynamicRules||[]};message.value='Dynamic node group rules saved';await load()}catch(e){groupError.value=e.message}finally{dynamicGroupSaving.value=false}}
function askConfirmation(message,action){confirmMessage.value=message;confirmAction.value=action;confirmOpen.value=true}
async function runConfirmation(){const action=confirmAction.value;confirmOpen.value=false;confirmAction.value=null;if(action){confirmBusy.value=true;try{await action()}finally{confirmBusy.value=false}}}
function removeGroupMember(node){if(!selectedGroup.value)return;askConfirmation(`Remove ${node.hostname} from ${selectedGroup.value.name}? Group policy assignments for this node may change immediately.`,async()=>{busy.value=true;groupError.value='';try{await api(`/node-groups/${selectedGroup.value.id}/members/${node.id}`,{method:'DELETE'});selectedGroup.value=await api(`/node-groups/${selectedGroup.value.id}`);await load();message.value=`${node.hostname} removed from ${selectedGroup.value.name}`}catch(e){groupError.value=e.message}finally{busy.value=false}})}
async function addToGroup(){if(!selected.value||!memberGroup.value)return;busy.value=true;error.value='';try{await api(`/node-groups/${memberGroup.value}/members`,{method:'POST',body:{nodeId:selected.value.id}});message.value=`${selected.value.hostname} added to group`;memberGroup.value='';selected.value=await api(`/nodes/${selected.value.id}`);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function removeFromGroup(group){
  if(!selected.value)return
  askConfirmation(`Remove ${selected.value.hostname} from ${group.name}? Managed rules from that group's policies may be removed from this node.`,async()=>{
    busy.value=true;error.value='';message.value=''
    try{const result=await api(`/node-groups/${group.id}/members/${selected.value.id}`,{method:'DELETE'});selected.value=await api(`/nodes/${selected.value.id}`);await load();message.value=`Removed from ${group.name}; cleaned ${result.cleanedPolicies.length} policy rule group(s)`}
    catch(e){error.value=e.message}
    finally{busy.value=false}
  })
}
async function retrain(){if(!selected.value)return;busy.value=true;error.value='';try{const session=await api(`/nodes/${selected.value.id}/training`,{method:'POST',body:{durationDays:Number(retrainDays.value)}});selected.value=await api(`/nodes/${selected.value.id}`);message.value=`Relearning started through ${new Date(session.endsAt).toLocaleString()}`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function beginEdit(){if(!selected.value)return;editForm.value={hostname:selected.value.hostname,fqdn:selected.value.fqdn||'',ip:selected.value.ip||'',deviceType:selected.value.device_type||selected.value.deviceType||'auto',managementType:selected.value.management_type||selected.value.managementType||(isSnmp(selected.value)?'snmp':'auto')};error.value='';detailOpen.value=false;editOpen.value=true}
async function saveEdit(){if(!selected.value)return;busy.value=true;error.value='';try{const fields=selected.value.ad_guid?{ip:editForm.value.ip.trim()||null,deviceType:editForm.value.deviceType,managementType:editForm.value.managementType}:{hostname:editForm.value.hostname.trim(),fqdn:editForm.value.fqdn.trim()||null,ip:editForm.value.ip.trim()||null,deviceType:editForm.value.deviceType,managementType:editForm.value.managementType};await api(`/nodes/${selected.value.id}`,{method:'PATCH',body:fields});selected.value=await api(`/nodes/${selected.value.id}`);editOpen.value=false;detailOpen.value=true;message.value=`${selected.value.hostname} updated`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function beginDelete(){deleteConfirmation.value=false;error.value='';detailOpen.value=false;deleteOpen.value=true}
async function deleteNode(){if(!selected.value||!deleteConfirmation.value)return;busy.value=true;error.value='';try{const name=selected.value.hostname;await api(`/nodes/${selected.value.id}`,{method:'DELETE',body:{confirmed:true}});deleteOpen.value=false;detailOpen.value=false;selected.value=null;message.value=`${name} removed from inventory`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="view"><PageHeader eyebrow="ASSETS / WINDOWS NODES" :title="activeTheme==='enterprise'?'Monitored assets':'Node inventory'" description="Onboard, inspect and verify firewall hosts"><button class="button primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> Add node</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><nav class="view-tabs" aria-label="Inventory sections"><button type="button" :class="{active:activeTab==='assets'}" @click="activeTab='assets'">Assets <span>{{nodes.length}}</span></button><button type="button" :class="{active:activeTab==='groups'}" @click="activeTab='groups'">Node groups <span>{{groups.length}}</span></button></nav><section v-if="activeTab==='assets'" class="panel glass"><div class="panel-title"><div><span class="eyebrow">MANAGED ASSETS</span><h2>{{nodes.length}} nodes</h2></div><div class="table-tools asset-toolbar"><input v-model="search" @input="assetPage=1" class="search" placeholder="Search hostname, address, OS" aria-label="Search nodes"><select v-model="assetFilter" @change="assetPage=1" aria-label="Filter assets"><option value="all">All assets</option><option value="managed">Managed / learning</option><option value="unmanaged">Unmanaged</option><option value="reachable">Reachable</option><option value="unreachable">Unreachable</option></select><label class="page-size">Rows <select v-model.number="assetPageSize" @change="changeAssetPageSize"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="icon-button" @click="load" title="Refresh"><i class="mdi mdi-refresh"></i></button></div></div><div class="table-wrap"><table><thead><tr><th><button type="button" class="asset-sort" @click="sortAssets('hostname')">HOSTNAME</button></th><th><button type="button" class="asset-sort" @click="sortAssets('address')">ADDRESS</button></th><th>OS</th><th>MODE</th><th>SOURCE</th><th>FIREWALL</th><th>VERIFY</th><th><button type="button" class="asset-sort" @click="sortAssets('status')">STATUS</button></th><th>LAST SEEN</th><th aria-label="Actions"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="node in filtered" :key="node.id" @click="select(node)" @contextmenu="openContextMenu($event,node)" @keydown.shift.f10="openContextMenu($event,node)" class="click-row" tabindex="0"><td><i class="mdi mdi-monitor"></i> <strong>{{node.hostname}}</strong></td><td class="mono">{{node.ip||node.fqdn||'—'}}</td><td>{{node.os_version||'Unknown'}}</td><td>{{isSnmp(node)?'SNMP':node.connection_mode}}<span v-if="node.agent_required" class="status pending inventory-agent-required">Agent required</span></td><td><span class="status" :class="node.ad_missing?'failed':node.ad_guid?'reachable':'unknown'">{{node.ad_missing?'AD missing':node.inventory_source||'manual'}}</span></td><td><span class="status" :class="isSnmp(node)?'reachable':firewallLabel(node).toLowerCase()">{{firewallLabel(node)}}</span></td><td><span class="status" :class="node.managementVerification?.status||'unknown'" :title="node.managementVerification?.reason||'Management check pending'">{{node.managementVerification?.label||'Unchecked'}}</span></td><td><span class="status" :class="node.status">{{node.status}}</span></td><td>{{node.last_seen_at?new Date(node.last_seen_at).toLocaleString():'Never'}}</td><td><button type="button" class="asset-menu-trigger icon-button" :aria-label="`Actions for ${node.hostname}`" title="Node actions" @click.stop="openContextMenu($event,node)"><i class="mdi mdi-dots-vertical"></i></button></td></tr><tr v-if="!filtered.length"><td colspan="10" class="empty-table">{{nodes.length?'No nodes match your filters.':'No nodes yet. Add a Windows host to begin.'}}</td></tr></tbody></table></div><div class="asset-pagination"><span>Showing {{filteredRows.length?((assetPage-1)*assetPageSize+1):0}}–{{Math.min(assetPage*assetPageSize,filteredRows.length)}} of {{filteredRows.length}}</span><div class="inline-actions"><button type="button" class="button small secondary" :disabled="assetPage<=1" @click="changeAssetPage(assetPage-1)">Previous</button><span>Page {{assetPage}} / {{assetTotalPages}}</span><button type="button" class="button small secondary" :disabled="assetPage>=assetTotalPages" @click="changeAssetPage(assetPage+1)">Next</button></div></div></section><section v-if="activeTab==='groups'" class="panel glass"><div class="panel-title"><div><span class="eyebrow">FLEET ORGANIZATION</span><h2>Node groups</h2></div><span class="count-chip">{{groups.length}} groups</span></div><div class="table-wrap"><table><thead><tr><th>GROUP</th><th>ASSETS</th><th>POLICY SCOPE</th><th>ACCESS</th><th aria-label="Actions"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="group in groups" :key="group.id" class="click-row" tabindex="0" @click="openGroup(group)" @keydown.enter="openGroup(group)"><td><strong>{{group.name}}</strong><span v-if="group.dynamicEnabled" class="status pending dynamic-badge">Dynamic</span></td><td>{{group.count??group.member_count??0}}</td><td>{{group.policy_count??'—'}}</td><td>{{group.canWrite?'Editable':'Read only'}}</td><td><button type="button" class="button small secondary" @click.stop="openGroup(group)">View assets</button></td></tr><tr v-if="!groups.length"><td colspan="5" class="empty-table">No node groups yet.</td></tr></tbody></table></div><form class="inline-form" @submit.prevent="createGroup"><input v-model="groupName" required placeholder="New node group" aria-label="New node group"><button class="button small secondary">Create group</button></form><DynamicGroupEditor v-model="dynamicGroup" /></section><GlassWindow v-model="groupOpen" :title="selectedGroup?.name||'Node group'" width="700px"><div v-if="selectedGroup"><p><strong>{{selectedGroup.count}} assets</strong> in this group <span v-if="selectedGroup.dynamicEnabled" class="status pending dynamic-badge">Dynamic</span></p><p v-if="selectedGroup.dynamicEnabled" class="muted">Next refresh: {{selectedGroup.dynamicNextEvaluationAt?new Date(selectedGroup.dynamicNextEvaluationAt).toLocaleString():'Queued'}}</p><p v-if="groupError" class="error-msg" role="alert">{{groupError}}</p><DynamicGroupEditor v-if="selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" v-model="selectedGroupDynamic" :disabled="dynamicGroupSaving" /><div v-if="selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" class="form-actions"><button type="button" class="button primary" :disabled="dynamicGroupSaving" @click="saveDynamicGroup">{{dynamicGroupSaving?'Saving…':'Save dynamic rules'}}</button></div><div v-for="member in selectedGroup.members" :key="member.id" class="group-member-row"><div><strong>{{member.hostname}}</strong><small>{{member.ip||member.fqdn||'No address'}} · {{member.status}}</small></div><button v-if="canEdit&&selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" class="button small danger" :disabled="busy" @click="removeGroupMember(member)">Remove</button></div><p v-if="!selectedGroup.members.length" class="empty-side">No assets in this group.</p></div></GlassWindow><GlassWindow v-model="formOpen" title="Add Windows node"><form class="form-grid" @submit.prevent="create"><label>Hostname<input v-model="form.hostname" required placeholder="server-01"></label><label>FQDN<input v-model="form.fqdn" placeholder="server-01.example.com"></label><label>IP address<input v-model="form.ip" placeholder="10.0.0.5"></label><p class="training-note">New hosts train automatically for {{trainingDays}} days before learned rules are applied.</p><label>Credential<select v-model="form.credentialIds[0]"><option :value="undefined">Select credential</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><div class="form-actions"><button type="button" class="button secondary" @click="formOpen=false">