e-actions"><button class="button secondary" :disabled="busy" @click="action('probe')"><i class="mdi mdi-lan-check"></i> Probe</button><button v-if="canActivate(selected)" class="button secondary" :disabled="busy" @click="activateAgentless(selected)"><i class="mdi mdi-shield-check-outline"></i> Verify management</button><button class="button secondary" :disabled="busy" @click="action('facts/refresh')"><i class="mdi mdi-refresh"></i> Collect facts</button><button class="button secondary" :disabled="busy" @click="action('dns/refresh')"><i class="mdi mdi-dns"></i> Refresh DNS</button><button v-if="canEdit" class="button secondary" :disabled="busy" @click="beginEdit"><i class="mdi mdi-pencil-outline"></i> Edit node</button><button v-if="canDelete&&!selected.ad_guid" class="button danger" :disabled="busy" @click="beginDelete"><i class="mdi mdi-delete-outline"></i> Remove node</button></div><div class="training-control"><div><span class="eyebrow">HOST TRAINING</span><strong>{{selected.training?.mode==='auto'?'Automatic':selected.training?.mode==='manual'?'Manual review':'No session'}} · {{selected.training?.status||'none'}}</strong><small v-if="selected.training?.last_error">{{selected.training.last_error}}</small></div><form v-if="!['active','review','applying','apply-failed'].includes(selected.training?.status)" class="training-restart" @submit.prevent="retrain"><label>Relearn for <input v-model.number="retrainDays" type="number" min="1" max="365" required> days</label><button class="button small secondary" :disabled="busy">Start relearning</button></form><router-link v-else-if="selected.training?.status==='apply-failed'" class="button small secondary" to="/logs">Retry in Logs</router-link></div><div v-if="['winrm','winrms'].includes(selected.transport)" class="audit-readiness"><div><span class="eyebrow">TRAFFIC AUDITING</span><strong :class="auditPolicy&&!auditPolicy.successEnabled?'danger-text':''">{{auditLoading?'Checking…':auditPolicy?.successEnabled?'Filtering Platform Connection success audit enabled':auditPolicy?'Success audit disabled':'Status unknown'}}</strong><small v-if="auditPolicy&&!auditPolicy.successEnabled">Enable this audit subcategory through Group Policy before automatic training can finish. Success auditing can generate many events.</small><small v-if="auditError" class="danger-text">{{auditError}}</small></div><div class="audit-actions"><button class="button small secondary" :disabled="auditLoading" @click="loadAuditPolicy">Check again</button><button v-if="canDelete&&auditPolicy&&(!auditPolicy.successEnabled||!auditPolicy.failureEnabled)" class="button small primary" :disabled="busy" @click="beginAuditEnable">Enable auditing</button></div></div><div class="node-groups"><h3>Node groups</h3><p v-if="error" class="error-msg" role="alert">{{error}}</p><div v-for="group in selected.groups||[]" :key="group.id" class="node-group-row"><span><i class="mdi mdi-server-network"></i> {{group.name}}</span><button v-if="canEdit&&group.canWrite&&group.id!=='winfire-global-all-nodes'" class="button small secondary" :disabled="busy" :aria-label="`Remove ${selected.hostname} from ${group.name}`" @click="removeFromGroup(group)">Remove</button></div><p v-if="!selected.groups?.length" class="empty-side">This node is not in a group.</p><div v-if="canEdit&&availableGroups.length" class="inline-form"><select v-model="memberGroup" aria-label="Node group"><option value="">Select group</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{group.name}}</option></select><button class="button small secondary" :disabled="busy||!memberGroup" @click="addToGroup">Add to group</button></div></div><div v-if="selected.probe" class="code-block">{{JSON.stringify(selected.probe,null,2)}}</div><NodeFacts :node="selected" :rule-page="rulePage" :rules-loading="rulesLoading" :rules-error="rulesError" @rules-page="loadRules"/><h3>DNS</h3><pre class="code-block">{{JSON.stringify(selected.dns||{},null,2)}}</pre></template></GlassWindow><GlassWindow v-model="auditEnableOpen" :title="`Enable auditing on ${selected?.hostname||'node'}`" width="520px"><div v-if="selected" class="form-grid"><p class="training-note">This enables success and failure auditing for Filtering Platform Connection on this Windows host. It can produce a high volume of Security events. Group Policy may override the local setting.</p><label class="account-checkbox confirm-checkbox"><input v-model="auditConfirmation" type="checkbox"> I understand this enables high volume Windows firewall auditing.</label><p v-if="error" class="error-msg" role="alert">{{error}}</p><div class="form-actions"><button class="button secondary" @click="auditEnableOpen=false;detailOpen=true">Cancel</button><button class="button primary" :disabled="busy||!auditConfirmation" @click="enableAuditPolicy">{{busy?'Enabling…':'Enable auditing'}}</button></div></div></GlassWindow><GlassWindow v-model="editOpen" :title="`Edit ${selected?.hostname||'node'}`" width="520px"><form v-if="selected" class="form-grid" @submit.prevent="saveEdit"><p v-if="selected.ad_guid" class="training-note">Active Directory manages this computer name and FQDN. Edit those fields in the directory.</p><label>Hostname<input v-model="editForm.hostname" required :disabled="!!selected.ad_guid"></label><label>FQDN<input v-model="editForm.fqdn" :disabled="!!selected.ad_guid" placeholder="server.example.com"></label><label>IP address<input v-model="editForm.ip" placeholder="10.0.0.5"></label><label>Node type<select v-model="editForm.deviceType"><option value="auto">Auto detect</option><option value="switch">Switch</option><option value="firewall">Firewall</option><option value="router">Router</option><option value="printer">Printer</option><option value="hypervisor">Hypervisor</option><option value="other">Other</option></select></label><label>Management type<select v-model="editForm.managementType"><option value="auto">Auto detect</option><option value="snmp">SNMP</option><option value="agentless">Agentless</option><option value="agent">Agent</option><option value="manual">Manual</option></select></label><p v-if="error" class="error-msg" role="alert">{{error}}</p><div class="form-actions"><button type="button" class="button secondary" @click="editOpen=false;detailOpen=true">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Saving…':'Save changes'}}</button></div></form></GlassWindow><GlassWindow v-model="deleteOpen" :title="`Remove ${selected?.hostname||'node'}`" width="520px"><div v-if="selected" class="form-grid"><p class="training-note">This removes the node from inventory. Historical logs and audit records remain. Remove assigned policies and their managed firewall rules first.</p><label class="account-checkbox confirm-checkbox"><input v-model="deleteConfirmation" type="checkbox"> I understand this removes the node from inventory.</label><p v-if="error" class="error-msg" role="alert">{{error}}</p><div class="form-actions"><button class="button secondary" @click="deleteOpen=false;detailOpen=true">Cancel</button><button class="button danger" :disabled="busy||!deleteConfirmation" @click="deleteNode">{{busy?'Removing…':'Remove node'}}</button></div></div></GlassWindow><div v-if="contextMenu" ref="contextMenuEl" class="asset-context-menu" role="menu" :style="{left:`${contextMenu.x}px`,top:`${contextMenu.y}px`}" @contextmenu.prevent>  <strong class="asset-context-title">{{contextMenu.node.hostname}}</strong>
